import frappe

def execute():
    images_link_dict = images_link()
    batch_size = 1000
    items = []
    for i, item in enumerate(images_link_dict):
        # create a batch of items
        items.append({"item": item, "image": images_link_dict[item]})
        if len(items) == batch_size or i == len(images_link_dict) - 1:
            frappe.enqueue(
                update_items_image_link,
                items=items,
                queue='default',
                timeout=300
            )
            items = []
    
def update_items_image_link(items):
    for item in items:
        frappe.db.set_value('Item', item["item"], 'image', item["image"], update_modified=False)
        
    frappe.db.commit()
    
    
        
def images_link():
    item_images = images_csv()
    item_link = {}
    items_images = item_images.split('\n')
    for item in items_images:
        parts = item.split(',')
        item_name = parts[0]
        image_link = parts[1]
        
        item_link[item_name] = image_link
        
    return item_link


